"""Visible pre-save checks and explicit purchase study choice."""
CSS='''
#po-final-check{padding:18px;border:1px solid var(--guide-border,#bfd2ed);border-radius:14px;background:var(--guide-surface,#fff);margin-bottom:18px}#po-final-check li{margin:10px 0}#po-final-check button{font:inherit;text-decoration:underline}#po-final-check [data-ok=true]{color:#08735e}#po-save-correction{padding:14px;border:2px solid #b42318;border-radius:10px;background:#fff1f0;color:#861a14}[data-theme=dark] #po-save-correction{background:#3c1c23;color:#ffdad6;border-color:#ff8a80}
'''
JS=r'''
(function(){
 const form=$('form'),review=document.createElement('section');review.id='po-final-check';$('po-guide-save-fields').prepend(review);
 let chosenFingerprint=null;
 function fingerprint(){const slot=window.purchasePaymentChoice;const terms=['unit_price','discount_mode','discount_value','vat_percent','shipping_mode','shipping_net','shipping_vat_percent','shipping_billed_by','due_date','shipping_due_date'].map(key=>{const input=$('po-neg-'+slot+'-'+key);return input&&!input.disabled?input.value:null});return JSON.stringify([$('dataset').value,$('article').value,$('supplier').value,form.elements.quantity.value,form.elements.order_date.value,terms])}
 form.addEventListener('purchasechoice',()=>{chosenFingerprint=fingerprint();refresh()});
 window.purchaseChoiceIsCurrent=()=>!!window.purchasePaymentChoice&&window.purchasePaymentChoice===window.purchaseNegotiationSelection()&&chosenFingerprint===fingerprint();
 function issues(){const out=[];const add=(message,target,slot)=>out.push({message,target,slot});
 if(!window.purchasePaymentChoice||window.purchasePaymentChoice!==window.purchaseNegotiationSelection())add('Elige las condiciones con las que quieres preparar los pagos.',$('po-option-studies'));
 else if(chosenFingerprint!==fingerprint())add('Has cambiado la cantidad, fecha o condiciones. Vuelve a elegir la propuesta antes de guardar.',$('po-option-studies'));
 const variants=typeof purchaseNegotiationDraft==='function'?purchaseNegotiationDraft():[];
 for(const entry of variants){const rows=entry.patch.payment_installments;if(rows===null||rows===undefined)continue;const title=entry.slot==='mine'?'Mi propuesta':'Propuesta del proveedor';if(!rows.length||rows.length>20)add(title+': el calendario está declarado pero necesita entre 1 y 20 cuotas.',$('proposal-payment-plan'),entry.slot);else for(const [i,row]of rows.entries()){if(!row.due_date||!Number.isFinite(Number(row.amount))||Number(row.amount)<=0)add(title+': revisa importe y vencimiento de la cuota '+(i+1)+'.',$('proposal-payment-plan'),entry.slot);}}
 if(!commercialQuote||commercialQuote.operation_total===null)add('Completa el cálculo del importe y los portes.',$('po-conditions'));
 return out}
 window.purchasePreSaveIssues=issues;
 function go(target){if(target===$('po-option-studies'))purchaseGuideNavigate('po-conditions',true);else if(target===$('proposal-payment-plan'))purchaseGuideNavigate('po-payments',true);else purchaseGuideNavigate('po-conditions',true);target.scrollIntoView({block:'center'});target.tabIndex=-1;target.focus({preventScroll:true})}
 function refresh(){if(document.body.dataset.purchaseMode!=='saved'&&$('save').getAttribute('aria-busy')!=='true')$('save').disabled=!commercialQuote;review.replaceChildren();const h=document.createElement('h3');h.textContent='REVISA LO QUE VAS A GUARDAR';review.append(h);const summary=document.createElement('p');summary.textContent=($('article').value||'Artículo pendiente')+' · Cantidad: '+(form.elements.quantity.value||'—')+' · '+(window.purchasePaymentChoice==='response'?'Propuesta del proveedor':window.purchasePaymentChoice==='mine'?'Mi propuesta':'Condiciones pendientes de elegir')+' · Total: '+(commercialQuote?.operation_total!==null&&commercialQuote?.operation_total!==undefined?money(commercialQuote.operation_total)+' €':'—');review.append(summary);let errors;try{errors=issues();for(const entry of purchaseNegotiationDraft()){const p=document.createElement('p'),rows=entry.patch.payment_installments;p.textContent=(entry.slot==='mine'?'Mi propuesta':'Propuesta del proveedor')+' · '+(rows===null||rows===undefined?'Sin reparto de cuotas declarado':rows.length+' cuotas · Total repartido: '+money(rows.reduce((sum,row)=>sum+Number(row.amount),0))+' €')+' · Vencimiento: '+(entry.patch.due_date||'Pendiente');review.append(p)}}catch(error){errors=[{message:error.message,target:$('proposal-payment-plan'),slot:error.message.startsWith('Mi propuesta')?'mine':error.message.startsWith('Propuesta del proveedor')?'response':null}]};const list=document.createElement('ul');for(const issue of errors){const li=document.createElement('li'),button=document.createElement('button');button.type='button';button.textContent=issue.message;button.onclick=()=>{if(issue.slot)window.purchaseOpenOptionCalendar(issue.slot);go(issue.target)};li.append(button);list.append(li)}if(!errors.length){const li=document.createElement('li');li.dataset.ok='true';li.textContent='Elección de condiciones comprobada. Revisa importes y fechas; al guardar se valida su coherencia.';list.append(li)}review.append(list);return errors}
 form.addEventListener('submit',event=>{if(document.body.dataset.purchaseMode==='saved')return;const errors=refresh();if(errors.length){event.preventDefault();event.stopImmediatePropagation();purchaseGuideNavigate('po-save',true);review.scrollIntoView({block:'center'})}},true);
 const correction=document.createElement('div');correction.id='po-save-correction';correction.hidden=true;$('notice').after(correction);
 new MutationObserver(()=>{const message=$('notice').textContent;correction.replaceChildren();correction.hidden=true;if(!message||/GUARDADA|Guardando/.test(message))return;const slot=message.startsWith('Mi propuesta')?'mine':message.startsWith('Propuesta del proveedor')?'response':null;const calendar=/cuota|calendario|vencimiento/i.test(message);if(!calendar)return;correction.hidden=false;const link=document.createElement('button');link.type='button';link.textContent='Corregir '+(slot==='mine'?'el calendario de Mi propuesta':slot==='response'?'el calendario de Propuesta del proveedor':'los pagos de la opción elegida');link.onclick=()=>{window.purchaseOpenOptionCalendar(slot||window.purchaseNegotiationSelection());go($('proposal-payment-plan'))};correction.append(link)}).observe($('notice'),{childList:true,subtree:true,characterData:true});
 for(const type of ['input','change'])form.addEventListener(type,refresh);form.addEventListener('reset',()=>{window.purchasePaymentChoice=null;chosenFingerprint=null;correction.hidden=true;queueMicrotask(refresh)});$('dataset').addEventListener('change',()=>{window.purchasePaymentChoice=null;chosenFingerprint=null;refresh()});new MutationObserver(refresh).observe($('proposal-cost-summary'),{childList:true,subtree:true,characterData:true});refresh();
})();
'''
